    use super::Internlm2ToolParser;
    use crate::test_utils::{collect_stream, split_by_chars, test_tools};
    use crate::{ToolParser, ToolParserOutput, ToolParserTestExt as _};

    fn build_tool_call(function_name: &str, parameters: &str) -> String {
        format!(
            r#"<|action_start|><|plugin|>{{"name":"{function_name}","parameters":{parameters}}}<|action_end|>"#
        )
    }

    #[test]
    fn internlm2_parse_complete_without_tool_call_keeps_text() {
        let mut parser = Internlm2ToolParser::new(&test_tools());
        let output = parser.parse_complete("Hello, world!").unwrap();

        assert_eq!(output.normal_text, "Hello, world!");
        assert!(output.calls.is_empty());
    }

    #[test]
    fn internlm2_preserves_special_tokens() {
        let parser = Internlm2ToolParser::new(&test_tools());
        assert!(parser.preserve_special_tokens());
    }

    #[test]
    fn internlm2_parse_complete_extracts_raw_json_arguments() {
        let mut parser = Internlm2ToolParser::new(&test_tools());
        let arguments = r#"{ "location": "Tokyo", "days": "3" }"#;
        let output = parser
            .parse_complete(&format!(
                "Let me check.\n{}",
                build_tool_call("get_weather", arguments)
            ))
            .unwrap();

        assert_eq!(output.normal_text, "Let me check.\n");
        assert_eq!(output.calls.len(), 1);
        assert_eq!(output.calls[0].tool_index, 0);
        assert_eq!(output.calls[0].name.as_deref(), Some("get_weather"));
        assert_eq!(output.calls[0].arguments, arguments);
    }

    #[test]
    fn internlm2_streaming_handles_split_markers() {
        let input = format!(
            "hello {}",
            build_tool_call("get_weather", r#"{"location":"Tokyo"}"#)
        );
        let chunks = split_by_chars(&input, 5);
        let mut parser = Internlm2ToolParser::new(&test_tools());

        let output = collect_stream(&mut parser, &chunks);

        assert_eq!(output.normal_text, "hello ");
        assert_eq!(output.calls.len(), 1);
        assert_eq!(output.calls[0].arguments, r#"{"location":"Tokyo"}"#);
    }

    #[test]
    fn internlm2_streaming_emits_argument_deltas() {
        let mut parser = Internlm2ToolParser::new(&test_tools());
        let chunks = [
            "preface <|action_start|>",
            "<|plugin|>{\"name\":\"get_weather\",\"parameters\":",
            "{\"location\":",
            "\"Beijing\"",
            "}",
            "}<|action_end|> suffix",
        ];

        let mut output = ToolParserOutput::default();
        for chunk in chunks {
            let next = parser.parse_chunk(chunk).unwrap();
            output.append(next);
        }
        output.append(parser.finish().unwrap());

        assert_eq!(output.normal_text, "preface  suffix");
        assert_eq!(
            output.coalesce_calls().calls[0].arguments,
            r#"{"location":"Beijing"}"#
        );
    }

    #[test]
    fn internlm2_finish_fails_incomplete_tool_call() {
        let mut parser = Internlm2ToolParser::new(&test_tools());
        parser
            .parse_chunk(r#"<|action_start|><|plugin|>{"name":"get_weather","parameters":{"location""#)
            .unwrap();

        let error = parser.finish().unwrap_err();

        expect!["tool parser parsing failed: incomplete InternLM2 tool call"]
            .assert_eq(&error.to_report_string());
    }
